p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);a=p.parse_args();a.directory.mkdir(parents=True,exist_ok=True);v=subprocess.run([str(a.executable),str(a.directory)],capture_output=True,timeout=15);(a.directory/'stdout.bin').write_bytes(v.stdout);(a.directory/'stderr.bin').write_bytes(v.stderr);assert v.returncode==0 and not v.stderr,(v.returncode,v.stdout,v.stderr);r=json.loads((a.directory/'boxed.json').read_text());properties={x.attrib['name']:x.attrib.get('value','')for x in ET.parse(a.directory/'boxed.xml').findall('.//property')};html=(a.directory/'boxed.html').read_text();step=r['steps'][0];assert step['location']=={'file':'declared.ts','line':123,'column':45,'origin':'explicit'};assert step['boxCallsite']=={'file':'helper.ts','line':4,'column':12,'origin':'callsite'};assert step['errorAttribution']=={'stepId':step['id'],'kind':'boxedCaller','primary':True,'location':{'file':'caller.ts','line':8,'column':15,'origin':'callsite'}};assert step['error']==step['receiptError']=='Error: original\n at authored.ts:77:9';prefix='native.step'+step['id']+'.';assert properties[prefix+'errorAttribution.file']=='caller.ts'and properties[prefix+'errorAttribution.line']=='8'and properties[prefix+'errorAttribution.column']=='15'and properties[prefix+'errorAttribution.primary']=='true';assert properties[prefix+'location.origin']=='explicit'and properties[prefix+'error']==step['error'];assert html.index('Primary boxed error location')<html.index('Step source file')and 'original authored error and stack preserved'in html;assert r['steps'][1]['errorAttribution']['kind']=='boxedCallsite'and 'errorAttribution'not in r['steps'][2]and 'errorAttribution'not in r['steps'][-1];print('PASS native boxed JSON/XML/HTML decoding with original raw errors')
